function downloadBitriseApp(ticketKey, folder, bitriseBuild, branch, workingDir) {
    if (!bitriseBuild || !bitriseBuild.appSlug || !bitriseBuild.workflowId) {
        console.log('No bitriseBuild config — skipping artifact download');
