    lines.push('> Automate EVERY test case listed here.\n');

    for (var i = 0; i < linkedTCs.length; i++) {
        var tc = linkedTCs[i];
        var f = tc.fields || {};
        var status = (f.status && f.status.name) || 'Unknown';
