        var status = (f.status && f.status.name) || 'Unknown';
        var priority = (f.priority && f.priority.name) || 'Unknown';

        lines.push('---\n');
        lines.push('## ' + tc.key + ': ' + (f.summary || '(no summary)'));
        lines.push('**Status**: ' + status + '  **Priority**: ' + priority + '\n');

