        try { return file_read(opts); } catch (e) { return null; }
    };

    var freshConfigLoader = loadModule(
        'js/configLoader.js',
        makeRequire({ './config.js': configModule }),
        { file_read: fileReadMock }
    );

    var allMocks = Object.assign({
        jira_move_to_status: function() {},
        jira_search_by_jql: function() { return []; },
        jira_get_ticket: function(opts) { return { key: opts.key || opts, fields: { comment: { comments: [] } } }; },
        file_write: function() {},
        file_read: fileReadMock,
        cli_execute_command: function() { return ''; }
    }, mocks);

    var m = loadModule(
        'js/preCliMobileTestAutomationSetup.js',
        makeRequire({
            './configLoader.js': freshConfigLoader,
            './config.js': configModule,
            './common/pullRequest.js': {
                buildTargetedOriginFetchCommand: function(branches) {
                    var list = (branches || []).filter(function(b) { return b; });
                    if (!list.length) return null;
                    return 'git -c fetch.recurseSubmodules=no fetch origin ' + list.map(function(b) {
                        return '+refs/heads/' + b + ':refs/remotes/origin/' + b;
                    }).join(' ');
                },
                buildOriginFetchCommand: function(refSpec) {
                    return 'git -c fetch.recurseSubmodules=no fetch origin' + (refSpec ? ' ' + refSpec : '');
                }
            }
        }),
        allMocks
    );
    return m;
}

