               line.indexOf('COMMAND=') === -1 &&
               line.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('\n').trim();
}

/** Run a git / shell command inside the test automation repo working directory. */
function runInRepo(command, workingDir) {
